import os
import torch


class Config:
    # ---------------------------------------------------------
    # 1. Paths
    # ---------------------------------------------------------
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Ensure working and submission directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # Metadata files (generated by the metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Image directories
    # Note: Metadata file_path columns are relative to INPUT_DIR

    # Output paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "siamese_resnet18.pth")
    EMBEDDINGS_CACHE_PATH = os.path.join(WORKING_DIR, "train_embeddings.npy")
    LABELS_CACHE_PATH = os.path.join(WORKING_DIR, "train_labels.npy")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ---------------------------------------------------------
    # 2. System & Reproducibility
    # ---------------------------------------------------------
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Number of subprocesses for data loading

    # ---------------------------------------------------------
    # 3. Data & Image Processing
    # ---------------------------------------------------------
    IMG_SIZE = 224
    CHANNELS = 3

    # ImageNet Normalization Constants
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # ---------------------------------------------------------
    # 4. Model Hyperparameters
    # ---------------------------------------------------------
    BACKBONE = "resnet18"
    PRETRAINED = True
    EMBEDDING_DIM = 128  # Dimension of the output embedding vector

    # ---------------------------------------------------------
    # 5. Training Hyperparameters
    # ---------------------------------------------------------
    NUM_EPOCHS = 25
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Contrastive Loss Margin
    MARGIN = 1.0

    # ArcFace Hyperparameters
    ARC_S = 30.0
    ARC_M = 0.50

    # Early Stopping
    PATIENCE = 10  # Stop if validation loss doesn't improve for 10 epochs

    # ---------------------------------------------------------
    # 6. Inference / Post-Processing
    # ---------------------------------------------------------
    # Number of neighbors to retrieve
    KNN_K = 5

    # Distance threshold for 'new_whale' classification
    # If the distance to the nearest neighbor is > threshold, predict 'new_whale'
    # This can be tuned based on validation distribution
    NEW_WHALE_THRESHOLD = 0.7
